import { readFile, rm } from 'node:fs/promises';
import { join } from 'node:path';
import type { CatalogEntry } from '../../src/lib/catalog';
import {
  activeProviders,
  type ManualProvider,
  manualProviders,
  providerHomeHref,
} from '../../src/lib/providers';
import { atomicWrite } from './core';

const marker =
  '<!-- Generated by tools/manual. Edit src/data/manual-providers.json and manuals/ instead. -->';

export function renderProviderHome(provider: ManualProvider, entries: CatalogEntry[]): string {
  const manuals = entries
    .filter((entry) => entry.provider === provider.id)
    .sort((a, b) =>
      `${a.product}/${a.version}/${a.variant}/${a.name}/${a.section}/${a.id}`.localeCompare(
        `${b.product}/${b.version}/${b.variant}/${b.name}/${b.section}/${b.id}`,
        'en',
      ),
    );
  const lines = [
    '---',
    'title: HOME',
    `description: ${JSON.stringify(`${provider.label} の日本語マニュアル`)}`,
    `slug: ${JSON.stringify(providerHomeHref(provider.id).slice(1, -1))}`,
    'tableOfContents: false',
    'pagefind: false',
    'sidebar:',
    '  order: 1',
    '---',
    '',
    marker,
    '',
    provider.description,
    '',
    `[この提供元のマニュアルを検索する](/search/?provider=${encodeURIComponent(provider.id)})`,
    '',
    `収録済み: ${manuals.length} 件`,
  ];
  let previous = '';
  for (const entry of manuals) {
    const group = `${entry.product} / ${entry.version} / ${entry.variant}`;
    if (group !== previous) {
      lines.push('', `## ${group}`, '');
      previous = group;
    }
    lines.push(`- [${entry.name}(${entry.section})](${entry.href})`);
  }
  return `${lines.join('\n')}\n`;
}

export async function renderProviderHomes(root: string, entries: CatalogEntry[]) {
  activeProviders(entries.map((entry) => entry.provider));
  for (const provider of manualProviders.filter((item) => !item.legacyDirectory)) {
    const path = join(root, 'src/content/docs', provider.id, 'home.md');
    const previous = await readFile(path, 'utf8').catch((error: NodeJS.ErrnoException) => {
      if (error.code === 'ENOENT') return undefined;
      throw error;
    });
    if (previous !== undefined && !previous.includes(marker))
      throw new Error(`Refusing to overwrite an authored provider HOME: ${provider.id}`);
    if (entries.some((entry) => entry.provider === provider.id)) {
      await atomicWrite(path, renderProviderHome(provider, entries));
    } else if (previous !== undefined) {
      await rm(path);
    }
  }
}
